namespace UnityEngine {
 public class Object {public static int destroyed;public static void Destroy(Object o){destroyed++;}}
 public struct Vector3 {
  public float x,y,z;public Vector3(float a,float b,float c){x=a;y=b;z=c;}public static Vector3 up{get{return new Vector3(0,1,0);}}public static Vector3 zero{get{return new Vector3();}}
  public float magnitude{get{return (float)Math.Sqrt(x*x+y*y+z*z);}}public Vector3 normalized{get{return magnitude<1e-8?zero:this/magnitude;}}
  public static Vector3 operator+(Vector3 a,Vector3 b){return new Vector3(a.x+b.x,a.y+b.y,a.z+b.z);}public static Vector3 operator-(Vector3 a,Vector3 b){return new Vector3(a.x-b.x,a.y-b.y,a.z-b.z);}public static Vector3 operator-(Vector3 a){return a*-1;}public static Vector3 operator*(Vector3 a,float k){return new Vector3(a.x*k,a.y*k,a.z*k);}public static Vector3 operator/(Vector3 a,float k){return a*(1/k);}
  public static float Dot(Vector3 a,Vector3 b){return a.x*b.x+a.y*b.y+a.z*b.z;}public static Vector3 Cross(Vector3 a,Vector3 b){return new Vector3(a.y*b.z-a.z*b.y,a.z*b.x-a.x*b.z,a.x*b.y-a.y*b.x);}
  public static Vector3 Lerp(Vector3 a,Vector3 b,float t){return a+(b-a)*t;}public static Vector3 Scale(Vector3 a,Vector3 b){return new Vector3(a.x*b.x,a.y*b.y,a.z*b.z);}public static Vector3 ClampMagnitude(Vector3 a,float m){return a.magnitude>m?a.normalized*m:a;}public static Vector3 ProjectOnPlane(Vector3 a,Vector3 n){return a-n*Dot(a,n);}public static float Angle(Vector3 a,Vector3 b){return (float)(Math.Acos(Math.Max(-1,Math.Min(1,Dot(a.normalized,b.normalized))))*180/Math.PI);}
 }
 public struct Quaternion {
  internal System.Numerics.Quaternion q;public static Quaternion identity{get{return new Quaternion{q=System.Numerics.Quaternion.Identity};}}
  public static Quaternion Euler(float x,float y,float z){return new Quaternion{q=System.Numerics.Quaternion.CreateFromYawPitchRoll(y*(float)Math.PI/180,x*(float)Math.PI/180,z*(float)Math.PI/180)};}public static Quaternion Euler(Vector3 v){return Euler(v.x,v.y,v.z);}public static Quaternion Inverse(Quaternion a){return new Quaternion{q=System.Numerics.Quaternion.Inverse(a.q)};}public static Quaternion Slerp(Quaternion a,Quaternion b,float t){return new Quaternion{q=System.Numerics.Quaternion.Slerp(a.q,b.q,t)};}
  public static Quaternion operator*(Quaternion a,Quaternion b){return new Quaternion{q=a.q*b.q};}public static Vector3 operator*(Quaternion a,Vector3 b){var v=System.Numerics.Vector3.Transform(new System.Numerics.Vector3(b.x,b.y,b.z),a.q);return new Vector3(v.X,v.Y,v.Z);}
 }
 public struct Matrix4x4 {public Transform from,to;public bool inverse;public static Matrix4x4 operator*(Matrix4x4 a,Matrix4x4 b){return new Matrix4x4{from=b.from,to=a.to};}public Vector3 MultiplyPoint3x4(Vector3 v){return to.InverseTransformPoint(from.TransformPoint(v));}}
 public class Transform {public string name;public Transform parent;public Vector3 localPosition;public Quaternion localRotation=Quaternion.identity;public List<object> components=new List<object>();public List<Transform> children=new List<Transform>();public Vector3 position{get{return parent==null?localPosition:parent.TransformPoint(localPosition);}}public Quaternion rotation{get{return parent==null?localRotation:parent.rotation*localRotation;}}public Vector3 up{get{return rotation*Vector3.up;}}public Matrix4x4 worldToLocalMatrix{get{return new Matrix4x4{to=this};}}public Matrix4x4 localToWorldMatrix{get{return new Matrix4x4{from=this};}}public Vector3 TransformPoint(Vector3 v){return position+rotation*v;}public Vector3 InverseTransformPoint(Vector3 v){return Quaternion.Inverse(rotation)*(v-position);}public Vector3 TransformVector(Vector3 v){return rotation*v;}public Vector3 InverseTransformVector(Vector3 v){return Quaternion.Inverse(rotation)*v;}public T[] GetComponentsInChildren<T>(bool include){var l=new List<T>();foreach(var c in components)if(c is T)l.Add((T)c);foreach(var t in children)l.AddRange(t.GetComponentsInChildren<T>(include));return l.ToArray();}}
 public class Mesh:Object {public bool isReadable=true;public Vector3[] vertices;public void RecalculateNormals(){}public void RecalculateBounds(){}}
 public class MeshFilter {public Transform transform;public Mesh sharedMesh;private Mesh owned;public Mesh mesh{get{if(owned==null)owned=new Mesh{vertices=(Vector3[])sharedMesh.vertices.Clone()};return owned;}}}
 public class Collider {public bool enabled=true,isTrigger;public string name;public Transform transform;public Rigidbody attachedRigidbody;public Part owner;public T GetComponentInParent<T>()where T:class{return owner as T;}public bool CompareTag(string t){return name=="Ground_EVA_Airlock"&&t=="Airlock";}}
 public class BoxCollider:Collider {public Vector3 center,size;}
 public struct RaycastHit {public Collider collider;public Vector3 point,normal;public float distance;}
 public enum QueryTriggerInteraction{Ignore}public static class Physics {public const int DefaultRaycastLayers=-5;public static float slope,height;public static bool missing,saturated;public static Collider fakePart;public static int RaycastNonAlloc(Vector3 origin,Vector3 dir,RaycastHit[] outHits,float range,int mask,QueryTriggerInteraction q){if(saturated)return outHits.Length;if(missing)return 0;float t=(height+slope*origin.x-origin.y)/(dir.y-slope*dir.x);if(t<0||t>range)return 0;outHits[0]=new RaycastHit{collider=new Collider(),distance=t,point=origin+dir*t,normal=new Vector3(-slope,1,0).normalized};if(fakePart!=null){outHits[1]=new RaycastHit{collider=fakePart,distance=.1f,point=origin+dir*.1f,normal=Vector3.up};return 2;}return 1;}}
 public enum ForceMode{Force}public class Rigidbody {public bool isKinematic;public Vector3 angularVelocity,inertiaTensor=new Vector3(2,3,4),lastTorque;public Quaternion rotation=Quaternion.identity,inertiaTensorRotation=Quaternion.identity;public int calls;public void AddTorque(Vector3 v,ForceMode f){lastTorque=v;calls++;}}
 public static class Mathf {public static float Clamp(float v,float a,float b){return Math.Max(a,Math.Min(b,v));}public static float Clamp01(float v){return Clamp(v,0,1);}public static float Abs(float v){return Math.Abs(v);}public static float Max(float a,float b){return Math.Max(a,b);}public static float MoveTowards(float a,float b,float d){return Math.Abs(a-b)<=d?b:a+Math.Sign(b-a)*d;}}
 public static class Time {public static float deltaTime=.02f,fixedDeltaTime=.02f;}public static class Debug{public static void LogError(string s){throw new Exception(s);}}
}
