public class ConfigNode {public string name;public Dictionary<string,string> values=new Dictionary<string,string>();public List<ConfigNode> children=new List<ConfigNode>();public string GetValue(string k){return values.ContainsKey(k)?values[k]:null;}public ConfigNode[] GetNodes(string n){return children.FindAll(x=>x.name==n).ToArray();}}
public class PartModule {public Part part;public Vessel vessel{get{return part==null?null:part.vessel;}}public UIList Fields=new UIList(),Events=new UIList(),Actions=new UIList();public virtual void OnLoad(ConfigNode n){}public virtual void OnStart(StartState s){}public virtual string GetInfo(){return "";}}
