public class Part {public string name="test";public UnityEngine.Transform transform=new UnityEngine.Transform();public Vessel vessel;public UnityEngine.Rigidbody Rigidbody=new UnityEngine.Rigidbody();public bool noAutoEVAAny;public UnityEngine.Transform airlock;public Info partInfo;public List<Part> symmetryCounterparts=new List<Part>();public List<PartModule> modules=new List<PartModule>();public UnityEngine.Transform[] FindModelTransforms(string n){var t=new List<UnityEngine.Transform>();Find(transform,n,t);return t.ToArray();}static void Find(UnityEngine.Transform t,string n,List<UnityEngine.Transform> l){if(t.name==n)l.Add(t);foreach(var c in t.children)Find(c,n,l);}public T[] GetComponentsInChildren<T>(bool x){return transform.GetComponentsInChildren<T>(x);}public List<T> FindModulesImplementing<T>(){var l=new List<T>();foreach(var m in modules)if(m is T)l.Add((T)(object)m);return l;}}
