public class Vessel {public bool loaded=true,packed,Landed=true,Splashed;public Body mainBody=new Body();public UnityEngine.Vector3 srf_velocity;public Precalc precalc;public Controls ctrlState=new Controls();public List<Part> parts=new List<Part>();public List<T> FindPartModulesImplementing<T>(){var l=new List<T>();foreach(var p in parts)l.AddRange(p.FindModulesImplementing<T>());return l;}}
public class ModuleRWGroundTether:PartModule{public bool tetherEnabled;public static int releases;public void EnableTether(){tetherEnabled=true;}public static void ReleaseForVessel(Vessel v,string s){releases++;foreach(var t in v.FindPartModulesImplementing<ModuleRWGroundTether>())t.tetherEnabled=false;}}
